function CashCountForm({ close, expected, onClose, notify }) {
  const { execute } = useHotel();
  const allowed = useActionPermission(close ? 'CASH_CLOSE' : 'CASH_COUNT');
  const [countedAmount, setCountedAmount] = useState(expected);
  const [note, setNote] = useState('');
  const submit = (event) => { event.preventDefault(); const type = close ? 'CASH_CLOSE' : 'CASH_COUNT'; if (run(execute, { type, countedAmount: Number(countedAmount), note }, notify, close ? 'Caja cerrada' : 'Arqueo registrado', close ? 'La sesión quedó cerrada y conserva todo su historial.' : 'Se guardaron esperado, contado y diferencia.')) onClose(); };
  if (!allowed) return null;
  return <form className="form-grid" onSubmit={submit}><DetailGrid items={[{ label: 'Esperado', value: formatMoney(expected) }, { label: 'Contado', value: formatMoney(Number(countedAmount)) }, { label: 'Diferencia', value: formatMoney(Number(countedAmount) - expected) }]} /><label className="span-2">Monto contado<input type="number" min="0" step="any" value={countedAmount} onChange={(event) => setCountedAmount(event.target.value)} /></label><label className="span-2">Nota<textarea value={note} onChange={(event) => setNote(event.target.value)} /></label><div className="form-actions span-2"><button type="button" className="btn btn-outline" onClick={onClose}>Cancelar</button><button className="btn btn-primary">{close ? 'Cerrar caja' : 'Guardar arqueo'}</button></div></form>;
}

export function OperationalCashView({ notify }) {
  const { state } = useHotel();
  const [dialog, setDialog] = useState(null);
  const [selectedSessionId, setSelectedSessionId] = useState(null);
  const openSession = state.cashSessions.find((item) => item.status === 'Abierta');
  const session = state.cashSessions.find((item) => item.id === selectedSessionId) || openSession || state.cashSessions[0];
  const sessionMovements = state.cashMovements.filter((item) => item.sessionId === session?.id);
  const movements = [
    ...state.cashSessions.map((item) => ({
      id: item.id,
      createdAt: item.openedAt,
      type: 'Sesión',
      concept: <button className="btn btn-sm btn-outline" onClick={() => setSelectedSessionId(item.id)}>{session?.id === item.id ? 'Sesión seleccionada' : 'Ver sesión completa'}</button>,
      referenceId: `${item.status} · Cierre ${displayDateTime(item.closedAt)} · Esperado ${item.expectedAmount == null ? 'Pendiente' : formatMoney(item.expectedAmount)} · Contado ${item.countedAmount == null ? 'Pendiente' : formatMoney(item.countedAmount)} · Diferencia ${item.difference == null ? 'Pendiente' : formatMoney(item.difference)} · ${item.notes || 'Sin notas'}`,
      method: item.shift,
      responsible: item.responsible,
      amount: item.expectedAmount ?? item.openingAmount,
    })),
    ...sessionMovements,
  ];
  const income = movements.filter((item) => item.type === 'Ingreso').reduce((sum, item) => sum + item.amount, 0);
  const expenses = movements.filter((item) => item.type === 'Egreso').reduce((sum, item) => sum + item.amount, 0);
  const expected = (session?.openingAmount || 0) + income - expenses;
  return <div className="view-container"><PageHeader metadata={openSession ? `${openSession.id} · ${openSession.responsible} · ${openSession.shift}` : 'Sin caja abierta'} title="Caja" description="Apertura por turno, movimientos manuales, arqueo, cierre e historial auditable." /><div className="inline-actions">{openSession ? <><PermissionButton actionType="CASH_MOVEMENT" className="btn btn-outline" onClick={() => setDialog('movement')}>Ingreso / egreso</PermissionButton><PermissionButton actionType="CASH_COUNT" className="btn btn-primary" onClick={() => setDialog('count')}>Arqueo</PermissionButton></> : <PermissionButton actionType="CASH_OPEN" className="btn btn-primary" onClick={() => setDialog('open')}>Abrir caja</PermissionButton>}</div><MetricStrip items={[{ label: 'Fondo inicial', value: formatMoney(session?.openingAmount) }, { label: 'Ingresos del turno', value: formatMoney(income) }, { label: 'Egresos del turno', value: formatMoney(expenses) }, { label: 'Esperado', value: formatMoney(expected) }, { label: 'Diferencia', value: session?.difference == null ? 'Pendiente' : formatMoney(session.difference) }]} />{openSession ? <section className="card"><SectionHeader eyebrow="Sesión abierta" title="Control del turno" action={<PermissionButton actionType="CASH_CLOSE" className="btn btn-outline" onClick={() => setDialog('close')}>Cerrar caja</PermissionButton>} /><DetailGrid items={[{ label: 'Responsable', value: openSession.responsible }, { label: 'Turno', value: openSession.shift }, { label: 'Apertura', value: displayDateTime(openSession.openedAt) }, { label: 'Último conteo', value: openSession.countedAmount == null ? 'Pendiente' : formatMoney(openSession.countedAmount) }, { label: 'Estado', node: <StatusBadge>{openSession.status}</StatusBadge> }, { label: 'Notas', value: openSession.notes || 'Sin notas' }]} /></section> : <div className="alert-banner alert-banner-warning">La caja está cerrada. No se admiten movimientos hasta abrir un nuevo turno.</div>}<DataTable caption="Movimientos de la sesión seleccionada" columns={['Movimiento', 'Fecha', 'Tipo', 'Concepto', 'Referencia', 'Método', 'Responsable', 'Importe']}>{movements.length ? movements.map((item) => <tr key={item.id}><td>{item.id}</td><td>{displayDateTime(item.createdAt)}</td><td><StatusBadge>{item.type}</StatusBadge></td><td>{item.concept}</td><td>{item.referenceId || 'Manual'}</td><td>{item.method}</td><td>{item.responsible}</td><td>{formatMoney(item.amount)}</td></tr>) : null}</DataTable><section><SectionHeader eyebrow="Auditoría" title="Historial de sesiones" /><div className="record-list">{state.cashSessions.map((item) => <article key={item.id}><div><strong>{item.id} · {item.responsible} · {item.shift}</strong><span>{displayDateTime(item.openedAt)} · cierre {displayDateTime(item.closedAt)} · diferencia {item.difference == null ? 'pendiente' : formatMoney(item.difference)}</span></div><StatusBadge>{item.status}</StatusBadge></article>)}</div></section><Dialog open={dialog === 'open'} onClose={() => setDialog(null)} title="Abrir caja"><CashOpenForm onClose={() => setDialog(null)} notify={notify} /></Dialog><Dialog open={dialog === 'movement'} onClose={() => setDialog(null)} title="Movimiento manual"><CashMovementForm onClose={() => setDialog(null)} notify={notify} /></Dialog><Dialog open={dialog === 'count' || dialog === 'close'} onClose={() => setDialog(null)} title={dialog === 'close' ? 'Cerrar caja' : 'Registrar arqueo'}><CashCountForm close={dialog === 'close'} expected={expected} onClose={() => setDialog(null)} notify={notify} /></Dialog></div>;
}

function IncidentEditor({ incident, onClose, notify }) {
  const { state, execute } = useHotel();
  const canCreate = useActionPermission('INCIDENT_CREATE');
  const canUpdate = useActionPermission('INCIDENT_UPDATE');
  const progressActionType = incident?.status === 'Cerrada' ? 'INCIDENT_REOPEN' : 'INCIDENT_PROGRESS';
  const canProgress = useActionPermission(progressActionType);
  const [form, setForm] = useState(incident ? { responsible: incident.responsible, priority: incident.priority, evidence: '', solution: incident.solution || '', note: '' } : { type: 'Servicio', roomId: '', description: '', priority: 'Media', responsible: 'Por asignar', evidence: '', blocksRoom: false });
  const set = (key, value) => setForm((current) => ({ ...current, [key]: value }));
  if (incident) {
    const save = () => run(execute, { type: 'INCIDENT_UPDATE', incidentId: incident.id, payload: form }, notify, 'Incidencia actualizada', 'Responsable, prioridad y evidencia quedaron sincronizados.');
    const advance = () => { if (run(execute, { type: 'INCIDENT_PROGRESS', incidentId: incident.id, expectedStatus: incident.status, note: form.note || form.solution }, notify, 'Incidencia avanzada', 'El origen vinculado y la habitación quedaron sincronizados.')) onClose(); };
    const reopen = () => { if (run(execute, { type: 'INCIDENT_REOPEN', incidentId: incident.id, reason: form.note }, notify, 'Incidencia reabierta', 'La habitación recuperó su bloqueo cuando correspondía.')) onClose(); };
    if (!canUpdate && !canProgress) return null;
    return <div className="form-grid"><label>Responsable<input value={form.responsible} onChange={(event) => set('responsible', event.target.value)} /></label><label>Prioridad<select value={form.priority} onChange={(event) => set('priority', event.target.value)}>{['Baja', 'Media', 'Alta', 'Urgente'].map((item) => <option key={item}>{item}</option>)}</select></label><label className="span-2">Nueva evidencia<input value={form.evidence} onChange={(event) => set('evidence', event.target.value)} /></label><label className="span-2">Solución<textarea value={form.solution} onChange={(event) => set('solution', event.target.value)} /></label><label className="span-2">Nota / motivo<textarea value={form.note} onChange={(event) => set('note', event.target.value)} /></label><div className="form-actions span-2">{canUpdate ? <PermissionButton actionType="INCIDENT_UPDATE" className="btn btn-outline" onClick={save}>Guardar datos</PermissionButton> : null}{canProgress ? incident.status === 'Cerrada' ? <PermissionButton actionType={progressActionType} className="btn btn-primary" onClick={reopen}>Reabrir</PermissionButton> : <PermissionButton actionType={progressActionType} className="btn btn-primary" onClick={advance}>{incident.status === 'Resuelta' ? 'Cerrar y evaluar liberación' : 'Avanzar estado'}</PermissionButton> : null}</div></div>;
  }
  if (!canCreate) return null;
  const submit = (event) => { event.preventDefault(); if (run(execute, { type: 'INCIDENT_CREATE', payload: form }, notify, 'Incidencia creada', 'El registro y el bloqueo operativo quedaron auditados.')) onClose(); };
  return <form className="form-grid" onSubmit={submit}><label>Tipo<input value={form.type} onChange={(event) => set('type', event.target.value)} /></label><label>Habitación<select value={form.roomId} onChange={(event) => set('roomId', event.target.value)}><option value="">Sin habitación</option>{state.rooms.map((room) => <option key={room.id} value={room.id}>{room.id} · {room.status}</option>)}</select></label><label>Prioridad<select value={form.priority} onChange={(event) => set('priority', event.target.value)}>{['Baja', 'Media', 'Alta', 'Urgente'].map((item) => <option key={item}>{item}</option>)}</select></label><label>Responsable<input value={form.responsible} onChange={(event) => set('responsible', event.target.value)} /></label><label className="span-2">Descripción<textarea required value={form.description} onChange={(event) => set('description', event.target.value)} /></label><label className="span-2">Evidencia<input value={form.evidence} onChange={(event) => set('evidence', event.target.value)} /></label><label className="toggle-row span-2"><input type="checkbox" disabled={!form.roomId} checked={form.blocksRoom} onChange={(event) => set('blocksRoom', event.target.checked)} /><span>Bloquear operativamente la habitación</span></label><div className="form-actions span-2"><button type="button" className="btn btn-outline" onClick={onClose}>Cancelar</button><button className="btn btn-primary">Crear incidencia</button></div></form>;
}

export function OperationalIncidentsView({ notify }) {
  const { state } = useHotel();
  const canUpdateIncident = useActionPermission('INCIDENT_UPDATE');
  const canProgressIncident = useActionPermission('INCIDENT_PROGRESS');
  const canReopenIncident = useActionPermission('INCIDENT_REOPEN');
  const [editor, setEditor] = useState(undefined);
  return <div className="view-container"><PageHeader actionType="INCIDENT_CREATE" metadata="Cola coordinada con mantenimiento" title="Incidencias" description="Creación, asignación, avance, cierre, reapertura, evidencia y bloqueo operativo." action={<PermissionButton actionType="INCIDENT_CREATE" className="btn btn-primary" onClick={() => setEditor(null)}>Nueva incidencia</PermissionButton>} /><MetricStrip items={[{ label: 'Pendientes de cierre', value: state.incidents.filter((item) => item.status !== 'Cerrada').length }, { label: 'En proceso', value: state.incidents.filter((item) => item.status === 'En proceso').length }, { label: 'Urgentes', value: state.incidents.filter((item) => item.priority === 'Urgente').length }, { label: 'Cerradas', value: state.incidents.filter((item) => item.status === 'Cerrada').length }]} /><div className="operation-cards">{state.incidents.map((incident) => <article className="card operation-card" key={incident.id}><div className="row-between"><div><span className="eyebrow">{incident.id} · {incident.type}</span><h3>{incident.roomId ? `Habitación ${incident.roomId}` : 'Sin habitación'}</h3></div><StatusBadge>{incident.status}</StatusBadge></div><p>{incident.description}</p><DetailGrid compact items={[{ label: 'Responsable', value: incident.responsible }, { label: 'Prioridad', value: incident.priority }, { label: 'Referencia', value: incident.referenceId || 'Manual' }, { label: 'Evidencias', value: incident.evidence.length }, { label: 'Solución', value: incident.solution || 'Pendiente' }, { label: 'Bloquea habitación', value: incident.blocksRoom ? 'Sí' : 'No' }]} />{(canUpdateIncident || (incident.status === 'Cerrada' ? canReopenIncident : canProgressIncident)) ? <button className="btn btn-outline" onClick={() => setEditor(incident)}>Gestionar incidencia</button> : null}</article>)}</div><Dialog open={editor !== undefined} onClose={() => setEditor(undefined)} title={editor ? `Gestionar ${editor.id}` : 'Nueva incidencia'} wide><IncidentEditor incident={editor || null} onClose={() => setEditor(undefined)} notify={notify} /></Dialog></div>;
}

function SupplierEditor({ supplier, onClose, notify }) {
  const { execute } = useHotel();
  const allowed = useActionPermission(supplier ? 'SUPPLIER_UPDATE' : 'SUPPLIER_CREATE');
  const [form, setForm] = useState(supplier ? { ...supplier, productsText: supplier.products.join(', ') } : { businessName: '', ruc: '', contact: '', phone: '', email: '', productsText: '', averageDeliveryDays: 1, primary: false });
  const set = (key, value) => setForm((current) => ({ ...current, [key]: value }));
  const submit = (event) => { event.preventDefault(); const payload = { ...form, products: form.productsText.split(',').map((item) => item.trim()).filter(Boolean), averageDeliveryDays: Number(form.averageDeliveryDays) }; delete payload.productsText; const action = supplier ? { type: 'SUPPLIER_UPDATE', supplierId: supplier.id, payload } : { type: 'SUPPLIER_CREATE', payload }; if (run(execute, action, notify, supplier ? 'Proveedor actualizado' : 'Proveedor creado', 'El proveedor quedó disponible para los lotes de inventario.')) onClose(); };
  if (!allowed) return null;
  return <form className="form-grid" onSubmit={submit}><label className="span-2">Razón social<input required value={form.businessName} onChange={(event) => set('businessName', event.target.value)} /></label><label>RUC<input required value={form.ruc} onChange={(event) => set('ruc', event.target.value)} /></label><label>Contacto<input value={form.contact} onChange={(event) => set('contact', event.target.value)} /></label><label>Teléfono<input value={form.phone} onChange={(event) => set('phone', event.target.value)} /></label><label>Correo<input type="email" value={form.email} onChange={(event) => set('email', event.target.value)} /></label><label className="span-2">Categorías separadas por coma<input value={form.productsText} onChange={(event) => set('productsText', event.target.value)} /></label><label>Días de entrega<input type="number" min="0" value={form.averageDeliveryDays} onChange={(event) => set('averageDeliveryDays', event.target.value)} /></label><label className="toggle-row"><input type="checkbox" checked={form.primary} onChange={(event) => set('primary', event.target.checked)} /><span>Proveedor principal</span></label><div className="form-actions span-2"><button type="button" className="btn btn-outline" onClick={onClose}>Cancelar</button><button className="btn btn-primary">Guardar proveedor</button></div></form>;
}

export function OperationalSuppliersView({ notify }) {
  const { state, execute } = useHotel();
  const [editor, setEditor] = useState(undefined);
  const archive = (supplier) => run(execute, { type: 'SUPPLIER_ARCHIVE', supplierId: supplier.id, reason: 'Archivado desde proveedores' }, notify, 'Proveedor archivado', 'El proveedor permanece en el historial.');
  return <div className="view-container"><PageHeader actionType="SUPPLIER_CREATE" metadata="CRUD sin eliminación física" title="Proveedores" description="Altas, actualización y archivado con control de lotes activos." action={<PermissionButton actionType="SUPPLIER_CREATE" className="btn btn-primary" onClick={() => setEditor(null)}>Nuevo proveedor</PermissionButton>} /><MetricStrip items={[{ label: 'Proveedores', value: state.suppliers.length }, { label: 'Activos', value: state.suppliers.filter((item) => item.status !== 'Archivado').length }, { label: 'Principales', value: state.suppliers.filter((item) => item.primary && item.status !== 'Archivado').length }, { label: 'Lotes vinculados', value: state.inventory.filter((item) => item.supplierId).length }]} /><div className="operation-cards">{state.suppliers.map((supplier) => <article className="card operation-card" key={supplier.id}><div className="row-between"><div><span className="eyebrow">{supplier.id} · RUC {supplier.ruc}</span><h3>{supplier.businessName}</h3></div><StatusBadge>{supplier.status || 'Activo'}</StatusBadge></div><DetailGrid compact items={[{ label: 'Contacto', value: supplier.contact }, { label: 'Teléfono', value: supplier.phone }, { label: 'Correo', value: supplier.email }, { label: 'Entrega', value: `${supplier.averageDeliveryDays} día(s)` }, { label: 'Categorías', value: supplier.products.join(', ') || 'Sin categorías' }, { label: 'Lotes activos', value: state.inventory.filter((item) => item.supplierId === supplier.id && item.status !== 'Archivado').length }]} /><div className="inline-actions">{supplier.status !== 'Archivado' ? <><PermissionButton actionType="SUPPLIER_UPDATE" className="btn btn-outline" onClick={() => setEditor(supplier)}>Editar</PermissionButton><PermissionButton actionType="SUPPLIER_ARCHIVE" className="btn btn-outline" onClick={() => archive(supplier)}>Archivar</PermissionButton></> : <span>Histórico</span>}</div></article>)}</div><Dialog open={editor !== undefined} onClose={() => setEditor(undefined)} title={editor ? `Editar ${editor.id}` : 'Nuevo proveedor'} wide><SupplierEditor supplier={editor || null} onClose={() => setEditor(undefined)} notify={notify} /></Dialog></div>;
}
